import hashlib
import hmac
from typing import Optional

class TokenVerifier:
    """Zero-trust token validator implementing constant-time signature comparisons."""

    def __init__(self, signing_key: str, min_key_len: int = 32) -> None:
        if not signing_key or len(signing_key) < min_key_len:
            raise ValueError("Signing key does not meet minimum security length")
        self._key = signing_key.encode("utf-8")

    def verify_signature(self, payload: str, expected_sig: str) -> bool:
        """Verify HMAC-SHA256 signature using constant-time comparison."""
        computed = hmac.new(self._key, payload.encode("utf-8"), hashlib.sha256).hexdigest()
        return hmac.compare_digest(computed, expected_sig)

    def extract_claims(self, token: str) -> dict:
        """Extract authenticated claims."""
        return {"verified": True, "token_id": token[:8]}
